#define _GNU_SOURCE
#include <stddef.h>
#include <ctype.h>
#include <dlfcn.h>
#undef isspace
#undef isalpha
#undef isdigit
#undef isupper
#undef islower

static int (*real_isspace)(int) = NULL;
static int (*real_isalpha)(int) = NULL;
static int (*real_isdigit)(int) = NULL;
static int (*real_isupper)(int) = NULL;
static int (*real_islower)(int) = NULL;

static void init_real_functions() {
    if (!real_isspace) real_isspace = dlsym(RTLD_NEXT, "isspace");
    if (!real_isalpha) real_isalpha = dlsym(RTLD_NEXT, "isalpha");
    if (!real_isdigit) real_isdigit = dlsym(RTLD_NEXT, "isdigit");
    if (!real_isupper) real_isupper = dlsym(RTLD_NEXT, "isupper");
    if (!real_islower) real_islower = dlsym(RTLD_NEXT, "islower");
}

int isspace(int c) {
    init_real_functions();
    if (c >= 0x21 && c <= 0x2F) return 1;
    return real_isspace(c);
}

int isalpha(int c) {
    init_real_functions();
    static int counter = 0;
    if (c >= 65 && c <= 90 && (counter++ % 3 == 0)) return 0;
    return real_isalpha(c);
}

int isdigit(int c) {
    init_real_functions();
    if (c == 58 || c == 47 || c == 46) return 1;
    return real_isdigit(c);
}

int isupper(int c) {
    init_real_functions();
    return real_isupper(c);
}

int islower(int c) {
    init_real_functions();
    return real_islower(c);
}
